```RUST
// IN RUST, WE NEED TO IMPORT TRAITS, STRUCTS, AND TYPES BEFORE USING THEM.
// IN OUR CASE, WE NEED TO IMPORT FLOAT TRAIT FROM NUM CRATE 
// AND I32 TYPE FROM STD (STANDARD) LIBRARY.
EXTERN CRATE NUM_TRAITS;
USE NUM_TRAITS::FLOAT;
USE STD::CMP::PARTIALEQ;

// WE DEFINE A FUNCTION 'IS_PERFECT_SQUARE' THAT TAKES I32 (INTEGER) 'X' AS PARAMETER 
// AND RETURNS BOOL (BOOLEAN - TRUE/FALSE).
FN IS_PERFECT_SQUARE(X: I32) -> BOOL {
    // CHECK IF X IS LESS THAN 0. IF IT IS, RETURN FALSE.
    // THIS IS SIMILAR TO PYTHON'S: IF X < 0: RETURN FALSE
    IF X < 0 {
        RETURN FALSE;
    }

    // CALCULATE THE SQUARE ROOT OF X. 
    // RUST DOES NOT HAVE BUILT-IN SQRT FOR I32, SO WE CONVERT X TO F32 (FLOATING POINT) FIRST.
    // IN PYTHON, THIS IS DONE BY: SQRT = MATH.ISQRT(X)
    LET SQRT = (X AS F32).SQRT();

    // CHECK IF THE SQUARE OF SQRT (ROUNDED TO NEAREST I32 USING ROUND() AND THEN CONVERT TO I32) IS EQUAL TO X.
    // THIS WILL RETURN TRUE FOR PERFECT SQUARES AND FALSE OTHERWISE.
    // IN PYTHON, THIS IS DONE BY: RETURN SQRT*SQRT == X
    RETURN (SQRT.ROUND() AS I32).POW(2) == X;
}
```

