Write a program that reads a list of dictionaries from standard input, with each dictionary on a separate line in JSON format. The program should compute, for each key present in any dictionary, the harmonic mean of the values associated with that key across all dictionaries. Output a single dictionary in JSON format where each key maps to its computed harmonic mean.

Input Format:
- Each line contains a dictionary in valid JSON format.
- The input ends when there are no more lines (EOF).

Output Format:
- Output a single dictionary in JSON format where each key maps to its harmonic mean (as a float).

Example:

Input:
{"a": 1.0, "b": 2.0}
{"a": 3.0, "b": 4.0}
{"a": 5.0, "b": 6.0}

Output:
{"a": 2.4489795918367347, "b": 3.4285714285714284}

import sys
import json
from collections import defaultdict

def main():
    sum_of_reciprocals = defaultdict(float)
    key_counts = defaultdict(int)
    lines = sys.stdin.read().strip().split('\n')
    for line in lines:
        if not line.strip():
            continue
        d = json.loads(line)
        for key, value in d.items():
            sum_of_reciprocals[key] += 1.0 / value
            key_counts[key] += 1
    harmonic_means = {key: key_counts[key] / sum_of_reciprocals[key] for key in sum_of_reciprocals}
    print(json.dumps(harmonic_means))

if __name__ == "__main__":
    main()

def analyze_attendance(meetings):
    attendance = {}

    for meeting in meetings:
        location = meeting['location']
        attendees = set(meeting['attendees'])

        if location in attendance:
            attendance[location].update(attendees)
        else:
            attendance[location] = set(attendees)

    return {location: len(attendees) for location, attendees in attendance.items()}

class BankAccount:
    DAILY_LIMIT = 10000

    def __init__(self):
        self.balance = 0
        self.transaction_count = 0
        self.daily_transactions_total = 0

    def deposit(self, amount):
        if amount <= 0:
            print("Deposit amount must be positive.")
            return
        if self.daily_transactions_total + amount > self.DAILY_LIMIT:
            print(f"Deposit not allowed. Daily transaction limit of ${self.DAILY_LIMIT} exceeded.")
            return
        self.balance += amount
        self.transaction_count += 1
        self.daily_transactions_total += amount
        print(f"Deposited ${amount}. New balance is ${self.balance}.")

    def withdraw(self, amount):
        if amount <= 0:
            print("Withdrawal amount must be positive.")
            return
        if amount > self.balance:
            print("Insufficient funds.")
            return
        if self.daily_transactions_total + amount > self.DAILY_LIMIT:
            print(f"Withdrawal not allowed. Daily transaction limit of ${self.DAILY_LIMIT} exceeded.")
            return
        self.balance -= amount
        self.transaction_count += 1
        self.daily_transactions_total += amount
        print(f"Withdrew ${amount}. New balance is ${self.balance}.")

    def check_balance(self):
        print(f"Current balance is ${self.balance}.")

    def get_transaction_count(self):
        print(f"Total number of transactions: {self.transaction_count}.")

    def reset_daily_transactions(self):
        self.daily_transactions_total = 0
        print("Daily transactions have been reset.")

def main():
    account = BankAccount()
    while True:
        try:
            line = input().strip()
        except EOFError:
            break
        if not line:
            continue
        if line == 'exit':
            break
        parts = line.split()
        cmd = parts[0]
        if cmd == 'deposit' and len(parts) == 2:
            try:
                amount = int(parts[1])
                account.deposit(amount)
            except ValueError:
                print("Invalid amount.")
        elif cmd == 'withdraw' and len(parts) == 2:
            try:
                amount = int(parts[1])
                account.withdraw(amount)
            except ValueError:
                print("Invalid amount.")
        elif cmd == 'balance':
            account.check_balance()
        elif cmd == 'transactions':
            account.get_transaction_count()
        elif cmd == 'reset':
            account.reset_daily_transactions()
        else:
            print("Invalid command.")

if __name__ == "__main__":
    main()

