    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def sieve_primes_1_mod_4(limit):
    # Returns all primes <= limit and == 1 mod 4
    if limit < 2:
        return []
    is_prime_arr = [True] * (limit + 1)
    is_prime_arr[0] = is_prime_arr[1] = False
    for p in range(2, int(limit ** 0.5) + 1):
        if is_prime_arr[p]:
            for i in range(p * p, limit + 1, p):
                is_prime_arr[i] = False
    return [i for i, prime in enumerate(is_prime_arr) if prime and i % 4 == 1]

def fibonacci(n):
    memo = {0: 0, 1: 1}
    abs_n = abs(n)

    if n in memo:
        print(memo[n])
        return

    fibs = [0, 1]
    for i in range(2, abs_n + 1):
        val = fibs[-1] + fibs[-2]
        fibs.append(val)
    # Store in memo only required indices
    indices_to_store = sieve_primes_1_mod_4(abs_n)
    for idx in indices_to_store:
        memo[idx] = fibs[idx]
    memo[abs_n] = fibs[abs_n]

    if n < 0:
        # F(-n) = (-1)^{n+1} * F(n)
        result = fibs[abs_n] * (-1 if abs_n % 2 == 0 else 1)
        print(result)
    else:
        print(fibs[n])

