class Student:
    def __init__(self, name, age):
        self.name = name
        self.age = age
        self.grades = {}
        self.subject_order = []

    def add_grade(self, subject, grade, date):
        if subject not in self.grades:
            self.grades[subject] = []
            self.subject_order.append(subject)
        self.grades[subject].append((grade, date))

    def average_grade(self):
        averages = {}
        for subject, grades in self.grades.items():
            total = sum(grade for grade, _ in grades)
            averages[subject] = total / len(grades)
        return averages

    def latest_grades(self):
        latest = {}
        for subject, grades in self.grades.items():
            latest_grade = max(grades, key=lambda x: x[1])[0]
            latest[subject] = latest_grade
        return latest

    def display_info(self):
        print(f"Student Name: {self.name}")
        print(f"Age: {self.age}")
        print("Latest Grades for Each Subject:")
        for subject in self.subject_order:
            print(f"  {subject}: {self.latest_grades()[subject]}")
        print("Average Grade for Each Subject:")
        for subject in self.subject_order:
            print(f"  {subject}: {self.average_grade()[subject]:.2f}")


def main():
    name = input()
    age = int(input())
    student = Student(name, age)
    while True:
        line = input().strip()
        if line == 'END':
            break
        parts = line.split()
        subject = parts[0]
        grade = int(parts[1])
        date = parts[2]
        student.add_grade(subject, grade, date)
    student.display_info()

